function cockcroft(weight, age, sex, scr){
  weight=+weight; age=+age; scr=+scr; sex=(sex||'male').toLowerCase();
  if(!(weight>0)||!(age>0)||!(scr>0)) return {error:'体重/年龄/肌酐须为正'};
  var std=(140-age)*weight/(72*scr);
  if(sex==='female') std*=0.85;
  std=Math.round(std*10)/10;
  return {crcl:std, unit:'mL/min', sex:sex, note:'Cockcroft-Gault 估算，非医疗建议'};
}
var EXPORTS={cockcroft:cockcroft};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CockcroftForgePure = EXPORTS; }
